{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Practolol, the closest analogue by Morgan similarity (0.4909), has absolute oral bioavailability of 90–100% in humans; its shared aryloxypropanolamine core and similar polar substituent support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Penbutolol, which shares the tert-butylamino-hydroxypropoxy aryl motif, has 90% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Celiprolol, a direct structural relative containing a tert-butylamino-hydroxypropoxy aryl urea/carbamoyl system, has human oral bioavailability of 30–70%, all above the 20% threshold; this is the most chemically relevant anchor for the query's urea-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tertatolol, with the same tert-butylamino-hydroxypropoxy aryl ether, has absolute oral bioavailability of 64% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pafenolol, which contains a urea group and aryloxypropanolamine, has absolute oral bioavailability of 27% at 25 mg, still above the 20% threshold, supporting high F despite possible first-pass effects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Prenalterol is the only analogue with a reported F below 20% (~15%), but it lacks the urea/cyclohexyl system and has a free phenol that undergoes conjugation; this low-F evidence is poorly transferable to the query and is outweighed by the high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tert-butylamino aryloxypropanolamine urea, closely related to beta-blockers with experimentally high oral bioavailability (practolol 90–100%, penbutolol 90%, celiprolol 30–70%, tertatolol 64%, pafenolol 27–46%). Although rifampin co-treatment could lower exposure through enzyme/efflux induction, no direct evidence indicates a fall below the 20% threshold, and the closest structural analogues support high F.",
  "evidence_gaps": [
    "No direct rifampin co-administration data for the query or its close analogues.",
    "No human absolute bioavailability data for the exact query molecule.",
    "Uncertainty about the query's P-gp/CYP3A4 substrate status and the magnitude of any rifampin interaction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

